sections.syntax:
CREATE TABLE table_name (
  column1 datatype [constraint],
  column2 datatype [constraint],
  ...
);

examples.code:
CREATE TABLE Students (
  id        INT,
  name      VARCHAR(100),
  age       INT,
  email     VARCHAR(150)
);

CREATE TABLE Employees (
  emp_id    INT           PRIMARY KEY,
  full_name VARCHAR(100)  NOT NULL,
  salary    DECIMAL(10,2) NOT NULL,
  hire_date DATE
);

CREATE TABLE Products (
  product_id   INT          PRIMARY KEY,
  product_name VARCHAR(200) NOT NULL,
  price        DECIMAL(8,2) DEFAULT 0.00,
  sku          VARCHAR(50)  UNIQUE
);

CREATE TABLE Orders (
  order_id   INT PRIMARY KEY,
  customer_id INT NOT NULL,
  order_date  DATE,
  FOREIGN KEY (customer_id) REFERENCES Customers(customer_id)
);

CREATE TABLE Accounts (
  account_id INT          PRIMARY KEY,
  username   VARCHAR(50)  NOT NULL UNIQUE,
  age        INT          CHECK (age >= 18),
  balance    DECIMAL(12,2) CHECK (balance >= 0)
);

sections.syntax:
DROP TABLE table_name;

-- Safe version (no error if table doesn't exist):
DROP TABLE IF EXISTS table_name;

-- MySQL:
ALTER TABLE table_name
MODIFY COLUMN column_name new_datatype [constraint];

-- PostgreSQL / SQL Server:
ALTER TABLE table_name
ALTER COLUMN column_name TYPE new_datatype;

examples.code:
ALTER TABLE Employees
DROP COLUMN middle_name,
DROP COLUMN fax_number;

sections.syntax:
-- MySQL 8.0+ / PostgreSQL:
ALTER TABLE table_name
RENAME COLUMN old_name TO new_name;

-- MySQL older / SQL Server:
ALTER TABLE table_name
CHANGE old_name new_name datatype;

-- MySQL:
RENAME TABLE old_name TO new_name;

-- PostgreSQL:
ALTER TABLE old_name RENAME TO new_name;

-- SQL Server:
EXEC sp_rename 'old_name', 'new_name';

-- Single column:
CREATE TABLE table_name (
  col INT PRIMARY KEY,
  ...
);

-- Composite key:
CREATE TABLE table_name (
  col1 INT,
  col2 INT,
  PRIMARY KEY (col1, col2)
);

-- Add to existing table:
ALTER TABLE table_name ADD PRIMARY KEY (column_name);

examples.code:
CREATE TABLE Customers (
  customer_id INT PRIMARY KEY,
  name        VARCHAR(100) NOT NULL
);

CREATE TABLE Enrollments (
  student_id INT,
  course_id  INT,
  enrolled_on DATE,
  PRIMARY KEY (student_id, course_id)
);

CREATE TABLE Customers (
  customer_id INT PRIMARY KEY,
  name        VARCHAR(100)
);

CREATE TABLE Orders (
  order_id    INT PRIMARY KEY,
  customer_id INT,
  total       DECIMAL(10,2),
  FOREIGN KEY (customer_id) REFERENCES Customers(customer_id)
);

CREATE TABLE Users (
  user_id INT PRIMARY KEY,
  email   VARCHAR(150) UNIQUE,
  username VARCHAR(50) UNIQUE
);

CREATE TABLE Employees (
  emp_id  INT           PRIMARY KEY,
  name    VARCHAR(100)  NOT NULL,
  age     INT           CHECK (age >= 18 AND age <= 65),
  salary  DECIMAL(10,2) CHECK (salary > 0)
);

CREATE TABLE Orders (
  order_id INT PRIMARY KEY,
  status   VARCHAR(20) CHECK (status IN ('pending', 'shipped', 'delivered', 'cancelled'))
);

CREATE TABLE Products (
  product_id INT PRIMARY KEY,
  price      DECIMAL(8,2),
  discount   DECIMAL(5,2),
  CONSTRAINT chk_discount CHECK (discount < price)
);
